commit 8215a398219ae55ae3568a7a3946627dd3493e70
Author: Igor Demura <idemura@fb.com>
Date:   Sat Sep 10 20:41:20 2016 -0700

    Reimplement IS DISTINCT FROM as an operator

    This fixes incorrect result for IS DISTINCT FROM between structural
    types.

diff --git a/presto-main/src/main/java/com/facebook/presto/type/TimeWithTimeZoneOperators.java b/presto-main/src/main/java/com/facebook/presto/type/TimeWithTimeZoneOperators.java
index 877bb2f21a..a3c757b45b 100644
--- a/presto-main/src/main/java/com/facebook/presto/type/TimeWithTimeZoneOperators.java
+++ b/presto-main/src/main/java/com/facebook/presto/type/TimeWithTimeZoneOperators.java
@@ -14,6 +14,7 @@
 package com.facebook.presto.type;

 import com.facebook.presto.spi.ConnectorSession;
+import com.facebook.presto.spi.function.IsNull;
 import com.facebook.presto.spi.function.LiteralParameters;
 import com.facebook.presto.spi.function.ScalarOperator;
 import com.facebook.presto.spi.function.SqlType;
@@ -27,6 +28,7 @@ import static com.facebook.presto.spi.function.OperatorType.EQUAL;
 import static com.facebook.presto.spi.function.OperatorType.GREATER_THAN;
 import static com.facebook.presto.spi.function.OperatorType.GREATER_THAN_OR_EQUAL;
 import static com.facebook.presto.spi.function.OperatorType.HASH_CODE;
+import static com.facebook.presto.spi.function.OperatorType.IS_DISTINCT_FROM;
 import static com.facebook.presto.spi.function.OperatorType.LESS_THAN;
 import static com.facebook.presto.spi.function.OperatorType.LESS_THAN_OR_EQUAL;
 import static com.facebook.presto.spi.function.OperatorType.NOT_EQUAL;
@@ -124,4 +126,21 @@ public final class TimeWithTimeZoneOperators
     {
         return AbstractLongType.hash(unpackMillisUtc(value));
     }
+
+    @ScalarOperator(IS_DISTINCT_FROM)
+    @SqlType(StandardTypes.BOOLEAN)
+    public static boolean isDistinctFrom(
+            @SqlType(StandardTypes.TIME_WITH_TIME_ZONE) long left,
+            @IsNull boolean leftNull,
+            @SqlType(StandardTypes.TIME_WITH_TIME_ZONE) long right,
+            @IsNull boolean rightNull)
+    {
+        if (leftNull != rightNull) {
+            return true;
+        }
+        if (leftNull) {
+            return false;
+        }
+        return notEqual(left, right);
+    }
 }

